#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *a = (int *)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        scanf("%d", &a[i]);
    }

    qsort(a, N, sizeof(int), cmp);

    long long ans = 0;

    for (int k = 2; k < N; k++) {
        int l = 0;
        int r = k - 1;

        while (l < r) {
            if ((long long)a[l] + a[r] > a[k]) {
                ans += r - l;
                r--;
            } else {
                l++;
            }
        }
    }

    printf("%lld\n", ans);

    free(a);
    return 0;
}
